#include <stdio.h>

int main() {
  int i = 0;
  // while loop
  while (i < 5) {
    printf("While loop iteration: %d\n", i);
    i++;
  }

  // do-while loop
  i = 0;
  do {
    printf("Do-while loop iteration: %d\n", i);
    i++;
  } while (i < 5);

  // for loop
  for (i = 0; i < 5; i++) {
    printf("For loop iteration: %d\n", i);
  }
  return 0;
}
